const COMMANDS: u64 = 200;
const AT_ONCE: usize = 20;
/// The kinds of command below.
const KINDS: u64 = 14;
/// The kind that is cancelled before it starts, so it logs nothing.
const NEVER_STARTS: u64 = 11;
const GRACE: Duration = Duration::from_millis(100);
/// K2: no command takes longer (each is meant to take at most ~0.5 s).
const BOUND: Duration = Duration::from_secs(5);

    let pids = pids_in(&log);
    let started = (0..COMMANDS).filter(|i| i % KINDS != NEVER_STARTS).count();
    assert!(
        pids.len() >= started,
        "only {} pids logged for {started} commands",
        pids.len()
    );
    assert_dead_logged(&pids, Duration::from_secs(2), &log);
    let _ = std::fs::remove_file(&log);
}

/// K2: command `i` returns within `BOUND`.
async fn bounded(i: u64, fixture: PathBuf, log: PathBuf) {
    let done = tokio::time::timeout(BOUND, command(i, &fixture, &log)).await;
    assert!(
        done.is_ok(),
        "K2: command {i} (kind {}) did not return within {BOUND:?}",
        i % KINDS
    );
}

async fn command(i: u64, fixture: &Path, log: &Path) {
    let at = Duration::from_millis(spread(i) % 300);
    let token = CancellationToken::new();
    let mut cmd = Command::new(fixture);
    cmd.arg(pidlog(log)).grace(GRACE).cancel_on(token.clone());

5 => {
    let timeout = at + Duration::from_millis(10);
    let out = cmd
        .args(["ignore-term", "tree=2:resist", "hang"])
        .timeout(timeout)
        .run()
        .await;
    let out = out.expect("run");
    assert_eq!(out.exit.reason, Reason::Timeout, "{i}: {out:?}");
}
6 => {
    let (ran, ()) = tokio::join!(cmd.args(["tree=1", "hang"]).run(), cancel_at(at));
    let e = ran.expect_err("a cancelled run that never ends");
    assert_eq!(e.code(), ErrorCode::Aborted, "{i}: {e}");
    assert_eq!(e.result().map(|r| r.exit.reason), Some(Reason::Aborted), "{i}");

/// Every complete line of `log`, as a pid.
pub(super) fn pids_in(log: &Path) -> Vec<u32> {
    let text = std::fs::read_to_string(log).unwrap_or_default();
    text.split_inclusive('\n')
        .filter_map(|line| line.strip_suffix('\n')?.trim().parse().ok())
        .collect()
}

/// `assert_dead` for pids logged to `log` while other tests run fixtures too: on Windows, a pid only counts while
/// its command line still names `log` (a freed pid goes at once to another test's `omni-fixture`).
fn assert_dead_logged(pids: &[u32], within: Duration, log: &Path) {
    assert_dead_of(pids, within, Some(log));
}

fn assert_dead_of(pids: &[u32], within: Duration, log: Option<&Path>) {
    let deadline = Instant::now() + within;
    loop {
        let mut living: Vec<u32> = pids.iter().copied().filter(|&p| alive(p)).collect();
        if let Some(log) = log.filter(|_| !living.is_empty() && std::env::consts::OS == "windows") {
            let name = log
                .file_name()
                .map(|n| n.to_string_lossy().into_owned())
                .unwrap_or_default();
            living.retain(|&p| command_line(p).contains(&name));
        }
        if living.is_empty() {
            return;
        }
        assert!(
            Instant::now() < deadline,
            "alive per the OS: {living:?} (of {pids:?}){}",
            describe(&living)
        );
        std::thread::sleep(Duration::from_millis(10));
    }
}

//! A spawn whose message is larger than the channel's socket buffer (a large environment) still starts, with its
//! pipes: macOS refuses such a message whole when descriptors ride on it (EMSGSIZE).

use std::time::Duration;

use super::{binary, block, use_supervisor};
use crate::api::Command;

#[test]
fn a_spawn_with_a_large_environment_starts() {
    use_supervisor();
    let fixture = binary("omni-fixture");
    // 64 KiB: far above the 8 KiB socket buffer, under Linux's 128 KiB limit for one environment string.
    let big = "x".repeat(64 * 1024);
    block(async {
        let mut cmd = Command::new(&fixture);
        cmd.arg("getenv=OMNI_BIG")
            .env("OMNI_BIG", &big)
            .timeout(Duration::from_secs(30));
        let out = cmd.run().await.expect("run");
        assert!(out.exit.success(), "{:?}", out.exit);
        let text = out.stdout.to_string();
        assert!(
            text.starts_with("OMNI_BIG=\"xxx") && text.trim_end().len() == big.len() + 11,
            "{}",
            &text[..text.len().min(80)]
        );
    });
}

